<script setup>
import { computed, ref } from 'vue'
import { state, go, money, today, business, notify } from '../core/state'
import AppIcon from '../components/AppIcon.vue'
import AppModal from '../components/AppModal.vue'
const search = ref('')
const category = ref('Todos')
const city = ref('Todas as localizações')
const sort = ref('recommended')
const maxPrice = ref(10000)
const onlineOnly = ref(false)
const filtersOpen = ref(false)
const detailTab = ref('Serviços')
const categories = [{name:'Todos',label:'Todos os serviços',icon:'grid-2x2',color:'mint'},{name:'Beleza',label:'Beleza & estilo',icon:'scissors',color:'peach'},{name:'Bem-estar',label:'Spa & bem-estar',icon:'flower-2',color:'lavender'},{name:'Saúde',label:'Saúde & cuidados',icon:'heart-pulse',color:'blue'},{name:'Restauração',label:'Mesa & sabores',icon:'utensils',color:'yellow'}]
const cities = computed(() => [...new Set(state.db.businesses.map(b=>b.city))])
const favorites = computed(() => state.db.favorites || [])
const current = computed(() => business(state.selectedBusinessId))
const servicesFor = id => state.db.services.filter(s=>s.businessId===id && s.active)
const minPrice = id => Math.min(...servicesFor(id).map(s=>Number(s.price)),0 === servicesFor(id).length ? 0 : Infinity)
const results = computed(() => {
  const term = search.value.trim().toLocaleLowerCase('pt')
  let list = state.db.businesses.filter(b=>b.active && (state.view!=='favorites'||favorites.value.includes(b.id)) && (category.value==='Todos'||b.category===category.value) && (city.value==='Todas as localizações'||b.city===city.value) && (!onlineOnly.value||b.onlinePayment) && minPrice(b.id)<=maxPrice.value && (!term||[b.name,b.city,b.address,b.category,...servicesFor(b.id).map(s=>s.name)].join(' ').toLocaleLowerCase('pt').includes(term)))
  return list.sort(sort.value==='price' ? (a,b)=>minPrice(a.id)-minPrice(b.id) : sort.value==='name' ? (a,b)=>a.name.localeCompare(b.name) : (a,b)=>b.rating-a.rating)
})
const people = computed(() => state.db.staff.filter(p=>p.businessId===current.value?.id&&p.active))
const promotions = computed(() => state.db.promotions.filter(p=>p.active&&p.businessId===current.value?.id&&(!p.expires||p.expires>=today())))
const selectedCategory = name => categories.find(c=>c.name===name) || categories[0]
function openCompany(company) { state.selectedBusinessId=company.id;detailTab.value='Serviços';go('business') }
function favorite(id) { const index=state.db.favorites.indexOf(id);if(index<0)state.db.favorites.push(id);else state.db.favorites.splice(index,1) }
function book(serviceId) { state.bookingDraft={businessId:current.value.id,serviceId,date:today(),staffId:'',time:'',partySize:1,paymentMethod:'onsite',coupon:''};go('booking') }
function clearFilters() { search.value='';category.value='Todos';city.value='Todas as localizações';maxPrice.value=10000;onlineOnly.value=false }
function copyCoupon(code) { navigator.clipboard?.writeText(code).then(()=>notify('Cupão copiado.')).catch(()=>notify(`O seu cupão: ${code}`)) }
function photoError(event) { event.target.style.visibility='hidden'; event.target.parentElement.classList.add('photo-unavailable') }
</script>
<template>
  <div v-if="state.view!=='business'" class="discover-page">
    <header class="discovery-header"><div><span class="eyebrow">UM TEMPO SÓ SEU</span><h1>{{state.view==='favorites'?'Os seus lugares favoritos.':'O que vamos marcar hoje?'}}</h1><p>{{state.view==='favorites'?'Os espaços que quer voltar a visitar.':'Encontre o lugar certo. Escolha o seu momento.'}}</p></div><span class="discovery-date"><AppIcon name="calendar-days" :size="17"/>{{new Intl.DateTimeFormat('pt-MZ',{day:'numeric',month:'long'}).format(new Date())}}</span></header>
    <form class="discovery-search" @submit.prevent><div class="search-main"><AppIcon name="search"/><input v-model="search" placeholder="Serviço, estabelecimento ou especialidade" aria-label="Pesquisar serviços ou estabelecimentos"/><button v-if="search" type="button" class="icon-btn" title="Limpar pesquisa" @click="search=''"><AppIcon name="x" :size="16"/></button></div><div class="search-location"><AppIcon name="map-pin" :size="19"/><select v-model="city" aria-label="Localização"><option>Todas as localizações</option><option v-for="location in cities" :key="location">{{location}}</option></select></div><button class="btn primary search-submit" type="submit"><AppIcon name="search" :size="18"/><span>Pesquisar</span></button></form>
    <div class="category-navigation" aria-label="Categorias"><button v-for="item in categories" :key="item.name" :class="['category-button',{selected:category===item.name}]" :aria-pressed="category===item.name" @click="category=item.name"><span :class="['category-icon',item.color]"><AppIcon :name="item.icon" :size="23"/></span><span>{{item.label}}</span></button></div>
    <section class="discovery-results"><div class="section-heading"><div><h2>{{category==='Todos'?'Bons lugares, perto de si':selectedCategory(category).label}}</h2><p>{{results.length}} {{results.length===1?'estabelecimento disponível':'estabelecimentos disponíveis'}} <span class="separator-dot">·</span> Escolha o seu próximo momento</p></div><div class="results-tools"><select v-model="sort" aria-label="Ordenar estabelecimentos"><option value="recommended">Melhor avaliação</option><option value="price">Menor preço</option><option value="name">Nome</option></select><button class="btn secondary compact" @click="filtersOpen=true"><AppIcon name="sliders-horizontal" :size="17"/> Filtros<span v-if="onlineOnly||maxPrice<10000" class="filter-dot"></span></button></div></div>
      <div v-if="results.length" class="business-grid"><article v-for="company in results" :key="company.id" class="business-card"><div class="business-photo"><button class="photo-link" :aria-label="`Ver ${company.name}`" @click="openCompany(company)"><img :src="company.image" :alt="company.name" @error="photoError"/><span class="photo-fallback">{{company.name}}</span></button><span class="photo-category"><AppIcon :name="selectedCategory(company.category).icon" :size="13"/>{{company.category}}</span><button :class="['favorite-button',{selected:favorites.includes(company.id)}]" :aria-label="favorites.includes(company.id)?`Remover ${company.name} dos favoritos`:`Guardar ${company.name} nos favoritos`" :aria-pressed="favorites.includes(company.id)" @click="favorite(company.id)"><AppIcon name="heart" :size="18"/></button></div><div class="business-card-body"><div class="business-rating"><span><AppIcon name="star" :size="14"/>{{Number(company.rating||0).toFixed(1)}} <small>({{company.reviewCount||0}})</small></span><span class="subtle-tag">{{company.city}}</span></div><h3><button @click="openCompany(company)">{{company.name}}</button></h3><p class="business-address"><AppIcon name="map-pin" :size="14"/>{{company.address}}</p><div class="business-service-tags"><span v-for="item in servicesFor(company.id).slice(0,2)" :key="item.id">{{item.name}}</span></div><div class="business-card-footer"><span>A partir de <strong>{{money(minPrice(company.id))}}</strong></span><button class="round-link" :aria-label="`Ver serviços de ${company.name}`" title="Ver serviços" @click="openCompany(company)"><AppIcon name="arrow-up-right" :size="19"/></button></div></div></article></div>
      <div v-else class="empty-state"><AppIcon :name="state.view==='favorites'?'heart':'search'" :size="36"/><h3>{{state.view==='favorites'?'Ainda sem favoritos':'Não encontrámos resultados'}}</h3><p>{{state.view==='favorites'?'Guarde os estabelecimentos que mais gosta.':'Experimente outro serviço, categoria ou localização.'}}</p><button class="btn secondary" @click="clearFilters();go('explore')">{{state.view==='favorites'?'Explorar estabelecimentos':'Limpar filtros'}}</button></div>
    </section>
    <section class="discovery-bottom"><div class="editorial-note"><span class="category-icon peach"><AppIcon name="calendar-check" :size="24"/></span><div><h3>O seu dia merece espaço.</h3><p>Uma mesa entre amigos, um cuidado de rotina ou uma pausa para si.</p></div></div><button class="text-button" @click="state.role==='guest'?(state.returnView='appointments',go('auth')):go('appointments')">As minhas marcações <AppIcon name="arrow-right" :size="18"/></button></section>
    <AppModal v-model="filtersOpen" title="Filtrar estabelecimentos"><form @submit.prevent="filtersOpen=false"><label class="field">Preço inicial máximo <strong>{{money(maxPrice)}}</strong><input type="range" min="0" max="10000" step="100" v-model.number="maxPrice"/></label><label class="check-field"><input type="checkbox" v-model="onlineOnly"/>Aceita pagamento online</label><div class="form-actions"><button type="button" class="btn secondary" @click="clearFilters">Limpar</button><button class="btn primary">Ver {{results.length}} resultados</button></div></form></AppModal>
  </div>
  <div v-else-if="current" class="business-detail-page">
    <button class="text-button back-button" @click="go('explore')"><AppIcon name="arrow-left" :size="17"/>Voltar a explorar</button>
    <div class="business-detail-cover"><img :src="current.image" :alt="current.name" @error="photoError"/><span :class="['category-icon',selectedCategory(current.category).color]"><AppIcon :name="selectedCategory(current.category).icon" :size="28"/></span></div>
    <header class="page-header business-heading"><div><span class="eyebrow">{{current.category}} <span class="separator-dot">·</span> {{current.city}}</span><h1>{{current.name}}</h1><p><AppIcon name="map-pin" :size="16"/>{{current.address}} <span class="separator-dot">·</span><AppIcon name="star" :size="15"/>{{current.rating}} ({{current.reviewCount}} avaliações)</p></div><button class="btn secondary" @click="favorite(current.id)"><AppIcon name="heart" :size="17"/>{{favorites.includes(current.id)?'Guardado':'Guardar'}}</button></header>
    <div class="business-detail-layout"><section><div class="tabs"><button v-for="tab in ['Serviços','Equipa','Informações']" :key="tab" :class="{active:detailTab===tab}" @click="detailTab=tab">{{tab}}</button></div><template v-if="detailTab==='Serviços'"><div v-if="promotions.length" class="promotion-strip"><AppIcon name="tag" :size="20"/><span><strong>{{promotions[0].discount}}% para o seu próximo momento</strong><small>Cupão {{promotions[0].code}}</small></span><button class="icon-btn" title="Copiar cupão" aria-label="Copiar cupão" @click="copyCoupon(promotions[0].code)"><AppIcon name="copy" :size="17"/></button></div><div class="section-heading"><h2>Escolha o seu serviço</h2><span class="muted">{{servicesFor(current.id).length}} serviços</span></div><article v-for="item in servicesFor(current.id)" :key="item.id" class="service-choice"><span :class="['category-icon',selectedCategory(current.category).color]"><AppIcon :name="selectedCategory(current.category).icon"/></span><div><h3>{{item.name}}</h3><p>{{item.description}}</p><small><AppIcon name="clock" :size="13"/>{{item.duration}} min<span v-if="item.pricePerPerson"> · Por pessoa</span></small></div><div class="service-choice-action"><strong>{{money(item.price)}}</strong><button class="btn secondary compact" @click="book(item.id)">Marcar <AppIcon name="plus" :size="16"/></button></div></article><div v-if="!servicesFor(current.id).length" class="empty-state"><h3>Sem serviços disponíveis</h3><p>Este estabelecimento ainda está a preparar o seu catálogo.</p></div></template><div v-else-if="detailTab==='Equipa'" class="team-grid"><article v-for="person in people" :key="person.id" class="person-card"><span class="avatar">{{person.name.split(' ').map(x=>x[0]).slice(0,2).join('')}}</span><h3>{{person.name}}</h3><p>{{person.title}}</p><span class="badge success">{{person.serviceIds.length}} serviços</span></article><p v-if="!people.length" class="muted">As reservas são atribuídas aos recursos disponíveis do estabelecimento.</p></div><div v-else class="business-information"><h2>Sobre o estabelecimento</h2><p>{{current.description}}</p><h3>Horário de funcionamento</h3><div v-for="(day,i) in ['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado']" :key="day" class="hours-row"><span>{{day}}</span><strong>{{current.days.includes(i)?`${current.opens} - ${current.closes}`:'Encerrado'}}</strong></div><h3>Cancelamento e reagendamento</h3><p>Até {{current.cancelHours}} horas antes da marcação. Pagamentos já efectuados ficam registados como reembolso na simulação local.</p></div></section><aside class="business-info-aside"><h3>Encontre o seu momento</h3><p>{{current.description}}</p><div class="info-line"><AppIcon name="clock"/><span><strong>{{current.opens}} - {{current.closes}}</strong><small>Horário de funcionamento</small></span></div><div class="info-line"><AppIcon name="map-pin"/><span><strong>{{current.city}}</strong><small>{{current.address}}</small></span></div><a class="info-line" :href="`tel:${current.phone}`"><AppIcon name="phone"/><span><strong>{{current.phone}}</strong><small>Contactar estabelecimento</small></span></a><a class="info-line" :href="`mailto:${current.email}`"><AppIcon name="mail"/><span><strong>{{current.email}}</strong><small>E-mail</small></span></a><div class="business-payment-note"><AppIcon name="shield-check" :size="18"/><span>{{current.onlinePayment?'Pagamento online ou no local':'Pagamento no estabelecimento'}}</span></div></aside></div>
  </div>
</template>
